constexpr long factorial(int n) {
    return (n <= 1) ? 1 : n * factorial(n - 1);
}

// Compile-time variables
constexpr int Input = 5;
constexpr long MaxResult = factorial(Input);

// Usage requiring a constant expression
template<int N>
struct DataHolder {};

DataHolder<MaxResult> container;

// C++20: std::vector<int> v(MaxResult); // NOT CT (heap allocation)
int lookup[MaxResult]; // Array size must be CT
int val = factorial(10); // Runtime evaluation allowed if not constexpr context
